```js
function reservationMoves(ctx) {
  const body = ctx.body;
  const moves = body.moves;
  if (!Array.isArray(moves)) throw validationFailed('moves must be an array');
  if (moves.length < 1 || moves.length > 8) throw validationFailed('moves must contain 1 to 8 items');
  const seen = new Set();
  const items = moves.map(m => {
    const obj = requireObject(m, ...)
    const reference = obj.reference;
    if (typeof reference !== 'string' || reference.length === 0) throw validationFailed
    if (seen.has(reference)) throw validationFailed
    seen.add(reference)
    return { reference, tableId: optionalString(obj,'table_id'), startsAtLocal: optionalString(obj,'starts_at_local'), partySize: optionalPartySize(obj,'party_size') };
  });
  const reservations = items.map(it => {
    const r = M.index.reservationsByRef.get(it.reference);
    if (!r || r.user_id !== ctx.user.id) throw errors.notFound(...);
    return r;
  });
  const restaurantId = reservations[0].restaurant_id;
  if (!reservations.every(r => r.restaurant_id === restaurantId)) throw validationFailed('all bookings must be at the same restaurant');
  const restaurant = restaurantById(restaurantId);
  const now = Date.now();
  const planned = [];
  for (let i = 0; i < items.length; i++) {
    const r = reservations[i]; const it = items[i];
    if (r.status === 'cancelled') throw reservationCancelled;
    if (cutoffReached(r, restaurant, now)) throw cutoffPassed;
    const target = D.resolveTarget(restaurant, it.tableId ?? r.table_id, it.startsAtLocal ?? r.starts_at_local, it.partySize ?? r.party_size);
    planned.push({ reservation: r, target });
  }
  // occupancy
  const ignore = new Set(reservations.map(r => r.id));
  for (const p of planned) {
    if (!D.tableIsFree(restaurantId, p.target.table.id, p.target.startMs, p.target.endMs, ignore)) throw tableUnavailable;
  }
  for (let i=0;i<planned.length;i++) { for (let j=i+1;j<planned.length;j++) {
     if (same table && overlaps) throw tableUnavailable;
  }}
  // commit
  for (const p of planned) { apply }
  return { status: 201, body: { reservations: planned.map(p => V.reservationView(p.reservation)) } };
}
```

Note "Unchanged listed bookings retain their occupancy" — since they're in `ignore` and we compare their new (unchanged) interval against unlisted bookings via tableIsFree with ignore excluding ALL listed ones... wait, that means an unchanged listed booking is NOT checked against unlisted bookings. But if it's unchanged, it was already consistent with unlisted bookings. However, if booking A moves to a time overlapping unchanged booking B, B is in ignore so the check A-vs-B wouldn't fire. That's why I add the pairwise check among planned items. And A vs unlisted is caught by tableIsFree. B vs unlisted: unchanged, so still fine. Good.

Edge: two listed bookings on the same table overlapping after the move → pairwise catches it. ✓

