```js
function authenticate(req) {
  const header = req.headers.authorization;
  if (!header || typeof header !== 'string') throw errors.unauthenticated('a bearer token is required');
  const m = /^Bearer\s+(.+)$/i.exec(header.trim());
  if (!m) throw unauthenticated
  const userId = M.index.tokensByValue.get(m[1].trim());
  if (!userId) throw unauthenticated
  const user = M.index.usersById.get(userId);
  if (!user) throw unauthenticated
  return user;
}
