function gapBounds(zone, naiveMs) {
  const lo = naiveMs - DAY_MS, hi = naiveMs + DAY_MS;
  const offLo = offsetMsAt(lo, zone);
  const t = transitionIn(zone, lo, hi);
  if (t === null) return null;
