const MINUTE_BOUNDS = {
  slot_minutes: { min: 1, max: undefined },
  reservation_duration_minutes: { min: 1, max: undefined },
  cancellation_cutoff_minutes: { min: 0, max: CUTOFF_MAX_MINUTES },
};

function minuteValueError(value, label, bounds) {
  if (typeof value !== 'number' || !Number.isInteger(value)) return `${label} must be a whole number of minutes`;
  if (value < bounds.min) return bounds.min === 1 ? `${label} must be a positive whole number of minutes` : `${label} must not be negative`;
  if (bounds.max !== undefined && value > bounds.max) return `${label} must be at most ${bounds.max} minutes`;
  return null;
}

function requireMinute(value, field, label) {
  requireAmount(value, `${label} must be a number of minutes`);
  const problem = minuteValueError(value, label, MINUTE_BOUNDS[field]);
  if (problem) throw errors.validationFailed(problem);
  return value;
}

function hasValidMinuteSettings(r) {
  return Object.entries(MINUTE_BOUNDS).every(([field, bounds]) => minuteValueError(r[field], field, bounds) === null);
}
